import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET() {
    try {
        // Fetch all pending withdrawal requests
        const { data, error } = await supabase
            .from('financial_transactions')
            .select(`
                *,
                profiles:user_id (full_name, pix_key)
            `)
            .eq('type', 'Solicitação de Saque')
            .eq('status', 'Processando')
            .order('created_at', { ascending: true });

        if (error) throw error;

        return NextResponse.json(data);
    } catch (error: any) {
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}

export async function PATCH(request: Request) {
    try {
        const { transactionId, action, proofUrl } = await request.json();

        if (!transactionId || !action) {
            return NextResponse.json({ error: "Dados incompletos" }, { status: 400 });
        }

        // 1. Get the transaction and user_id
        const { data: tx, error: txError } = await supabase
            .from('financial_transactions')
            .select('*')
            .eq('id', transactionId)
            .single();

        if (txError || !tx) throw txError || new Error("Transação não encontrada");

        if (action === 'liquidate') {
            // Liquidate: Change status to Liquidado
            // Proof is manual for now, but we mark it as done
            const { error: updateTxError } = await supabase
                .from('financial_transactions')
                .update({
                    status: 'Liquidado',
                    description: proofUrl ? `${tx.description} (Comprovante: ${proofUrl})` : tx.description
                })
                .eq('id', transactionId);

            if (updateTxError) throw updateTxError;

            // Decrease processing balance
            const amount = Math.abs(Number(tx.amount));
            const { data: profile } = await supabase.from('profiles').select('balance_processing').eq('id', tx.user_id).single();

            await supabase
                .from('profiles')
                .update({ balance_processing: (Number(profile?.balance_processing) || 0) - amount })
                .eq('id', tx.user_id);

            return NextResponse.json({ success: true, message: "Saque liquidado com sucesso" });

        } else if (action === 'refuse') {
            // Refuse: Return money to available balance
            const { error: updateTxError } = await supabase
                .from('financial_transactions')
                .update({ status: 'Recusado' })
                .eq('id', transactionId);

            if (updateTxError) throw updateTxError;

            // Move balance back from processing to available
            const amount = Math.abs(Number(tx.amount));
            const { data: profile } = await supabase.from('profiles').select('balance_available, balance_processing').eq('id', tx.user_id).single();

            await supabase
                .from('profiles')
                .update({
                    balance_available: (Number(profile?.balance_available) || 0) + amount,
                    balance_processing: (Number(profile?.balance_processing) || 0) - amount
                })
                .eq('id', tx.user_id);

            return NextResponse.json({ success: true, message: "Saque recusado e saldo retornado" });
        }

        return NextResponse.json({ error: "Ação inválida" }, { status: 400 });

    } catch (error: any) {
        console.error("Erro na ação administrativa:", error);
        return NextResponse.json({ error: error.message }, { status: 500 });
    }
}
